def answers():
    children = {'A': ['B', 'C'], 'B': ['D', 'E'], 'C': [], 'D': [], 'E': []}
    parent = {c: p for p, cs in children.items() for c in cs}
    out = []
    for n in 'ABCDE':
        k = len(children[n])
        kind = '뿌리' if n not in parent else ('말단' if k == 0 else '중간')
        out += [k, kind]
    return out

